import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Count the number of ordered pairs (x, y) of positive integers with 0 < x < y < {upper_bound} such that the arithmetic mean of x and y is exactly {k} more than the geometric mean of x and y, and additionally gcd(x, y) = {h}. Give the exact count.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We enforce nontrivial instances by choosing parameters that guarantee many solutions.
# Let d be the integer difference of square roots: sqrt(y) - sqrt(x) = d.
# For the AM-GM offset k, we need d^2 = 2k, so d must be even and k = d^2/2.
d = 2 * rng.randint(2, 60)  # even and reasonably large
# Choose a divisor s of d, and impose gcd(x, y) = s^2. This yields gcd(t, d) = s where x = t^2.
# Build divisors of d.
divs = []
for i in range(1, d + 1):
    if d % i == 0:
        divs.append(i)
# Bias towards s > 1 to increase difficulty.
if rng.random() < 0.7 and len(divs) > 1:
    non1 = [v for v in divs if v != 1]
    s = rng.choice(non1)
else:
    s = rng.choice(divs)
# Choose target count of t-values (M) to ensure a substantial, nontrivial answer.
M = rng.randint(50, 2000)
# Construct upper_bound via sqrtN so that floor_sqrt(upper_bound - 1) = sqrtN,
# and M = floor((sqrtN - d)/s).
delta = rng.randint(0, max(0, s - 1))
sqrtN = d + s * M + delta
upper_bound = sqrtN * sqrtN + 1  # ensures floor_sqrt(upper_bound - 1) = sqrtN
k = (d * d) // 2
h = s * s
return {'upper_bound': upper_bound, 'k': k, 'h': h}

    def verifier(assign):
# Validate and compute the exact answer.
import math
# Basic key and type checks
for key in ('upper_bound', 'k', 'h'):
    if key not in assign:
        # Missing required parameter
        return (False, None)  # Missing key
    if not isinstance(assign[key], int):
        return (False, None)  # Types must be integers
upper_bound = assign['upper_bound']
k = assign['k']
h = assign['h']
if upper_bound <= 0 or k <= 0 or h <= 0:
    return (False, None)  # All parameters must be positive
# The AM-GM condition implies (sqrt(y) - sqrt(x))^2 = 2k, so d = sqrt(2k) must be integer.
two_k = 2 * k
d = math.isqrt(two_k)
if d * d != two_k:
    return (False, None)  # No solutions unless 2k is a perfect square
# gcd(x, y) = h forces x = t^2, y = (t + d)^2 and gcd(t, d) = sqrt(h). Hence h must be a perfect square dividing d^2.
s = math.isqrt(h)
if s * s != h or d % s != 0:
    return (False, None)  # gcd condition incompatible with AM-GM structure
# Upper bound constraint: y = (t + d)^2 < upper_bound. Let S = floor_sqrt(upper_bound - 1).
S = math.isqrt(upper_bound - 1)
# The allowable t are t = s*n with 1 <= n <= M, where M = floor((S - d)/s), and gcd(n, d/s) = 1.
M = (S - d) // s
if M < 2:
    return (False, None)  # Enforce nontrivial instances
D = d // s
# Count integers 1 <= n <= M with gcd(n, D) = 1 via inclusion-exclusion over prime factors of D.
def prime_factors_distinct(x):
    pf = []
    n = x
    if n % 2 == 0:
        pf.append(2)
        while n % 2 == 0:
            n //= 2
    p = 3
    while p * p <= n:
        if n % p == 0:
            pf.append(p)
            while n % p == 0:
                n //= p
        p += 2
    if n > 1:
        pf.append(n)
    return pf
if D == 1:
    answer = M
else:
    primes = prime_factors_distinct(D)
    total = 0
    m = len(primes)
    # Inclusion-exclusion: count of numbers <= M not divisible by any prime in primes
    for mask in range(1 << m):
        prod = 1
        bits = 0
        for i in range(m):
            if mask & (1 << i):
                prod *= primes[i]
                bits += 1
        term = M // prod
        if bits % 2 == 0:
            total += term
        else:
            total -= term
    answer = total
if answer <= 0:
    return (False, None)  # Should be nonzero for our generated instances
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

